/* ===== V126: المخزن الاحترافي — قيمة، أيام متبقية، حالة، فلترة ===== */
let stkFilter='all';
function stkUnitCost(k){
  const s=settings; try{
  if(k==='fish') return s.fish.kgCost||0; if(k==='fishbox') return s.fishbox.cost||0; if(k==='stubs') return s.stubs.cost||0;
  if(k==='mabooj') return maboojUnitCost(); if(k==='torshi') return torshiUnitCost(); if(k==='rice') return riceUnitCost();
  if(k==='tamur'){ const t=s.tamur, p=Math.floor(1000/(t.tubG||1))||1; return Math.round(t.kgCost/p)+(t.tubCost||0) }
  if(k==='mtubs') return s.mabooj.tubCost||0; if(k==='ttubs') return s.torshi.tubCost||0; if(k==='rtubs') return s.rice.tubCost||0; if(k==='tamtubs') return s.tamur.tubCost||0;
  if(k.indexOf('sup:')===0) return supPrice(k.slice(4))*1000;
  if(k.indexOf('cust:')===0) return ((s.custStock||{})[k.slice(5)]||{}).cost||0;
  }catch(_){} return 0;
}
function stkDaily(){
  const days=7, a=Date.now()-days*86400000, u={};
  const add=(k,v)=>{ if(v) u[k]=(u[k]||0)+v };
  orders.forEach(o=>{ if(o.ts<a||o.status==='cancel') return; const st=o.stk||orderStock(o);
    add('fish',st.fishKg); add('fishbox',st.fishbox); add('stubs',st.stubs);
    ['mabooj','torshi','rice','tamur'].forEach(k=>add(k,st[k]));
    add('mtubs',st.mabooj); add('ttubs',st.torshi); add('rtubs',st.rice); add('tamtubs',st.tamur);
    const sc=st.sauce; if(sc) ['red','black'].forEach(k=>{ const n=sc[k]||0; if(n) (settings.sauces[k].items||[]).forEach(it=>add('sup:'+it.name,(+it.use||0)*n/1000)) });
    if(st.rice){ const S=supAll(); Object.keys(S).forEach(n=>add('sup:'+n,(+S[n].perRice||0)*st.rice/1000)) }
  });
  const first=orders.reduce((m,o)=>Math.min(m,o.ts),Date.now()), span=Math.max(1,Math.min(days,Math.ceil((Date.now()-Math.max(a,first))/86400000)));
  Object.keys(u).forEach(k=>u[k]/=span); return u;
}
function stkRender(){
  const v=document.getElementById('stkView'); if(!v) return;
  document.getElementById('page-store').dataset.tab=stkTab;
  document.querySelectorAll('#stkTabs button').forEach(b=>b.classList.toggle('on',b.dataset.t===stkTab));
  if(stkTab!=='left'){ v.innerHTML=''; return }
  const D=stkDaily();
  const items=stkItems().map(it=>{ const c=document.getElementById(it.card), h=c&&c.querySelector('h3'); if(h){ const t=h.textContent.replace(/[▸▾]/g,'').trim(); if(t) it.n=t }
    if(it.u!=='كغم'&&it.u!==''){ const f=it.left; it.left=()=>Math.floor(f()+1e-6) }
    const l=it.left(), d=D[it.k]||0, days=d>0?l/d:null, low=stkLow(it,l);
    it.l=l; it.d=d; it.days=days; it.val=Math.max(0,l)*stkUnitCost(it.k);
    it.st=l<=0?'out':low?'low':(days!==null&&days<2)?'soon':'ok'; return it });
  const groups=[...new Set(items.map(i=>i.g))];
  const tot=items.reduce((s,i)=>s+i.val,0), nOut=items.filter(i=>i.st==='out').length, nLow=items.filter(i=>i.st==='low'||i.st==='soon').length;
  const fish=items.find(i=>i.k==='fish'), lastJ=(settings.stockLog||[]).filter(x=>x.t==='jard').slice(-1)[0];
  const ST={out:['خلص','out'],low:['قليل','low'],soon:['يخلص قريب','soon'],ok:['متوفر','ok']};
  const shown=items.filter(i=>stkFilter==='all'?true:stkFilter==='need'?i.st!=='ok':i.g===stkFilter);
  const gs=groups.filter(g=>shown.some(i=>i.g===g));
  v.innerHTML=`<div class="kpi">
      <div><span>قيمة المخزون</span><b>${fmt(Math.round(tot))}</b><small>د.ع</small></div>
      <div class="${nOut?'bad':''}"><span>خالص</span><b>${nOut}</b><small>مادة</small></div>
      <div class="${nLow?'warn':''}"><span>قليل أو يخلص قريب</span><b>${nLow}</b><small>مادة</small></div>
      <div><span>السمك بالحوض</span><b>${fish?fmt(Math.max(0,fish.l)):0}</b><small>كغم${fish&&fish.days!==null?' · يكفي '+(Math.round(fish.days*10)/10)+' يوم':''}</small></div>
    </div>
    <div class="chips" role="group" aria-label="فلترة">${[['all','الكل'],['need','يحتاج انتباه'+(nOut+nLow?' ('+(nOut+nLow)+')':'')],...groups.map(g=>[g,g])].map(([k,t])=>`<button type="button" data-f="${esc(k)}" class="${stkFilter===k?'on':''}">${esc(t)}</button>`).join('')}</div>
    ${gs.map(g=>`<section class="stk-g"><h4>${esc(g)}</h4><div class="stk-t">`+shown.filter(i=>i.g===g).map(it=>{ const lv=it.days===null?(it.l>0?1:0):Math.max(0,Math.min(1,it.days/7));
      return `<div class="stk-r st-${it.st}">
        <button class="stk-n" data-card="${esc(it.card)}" type="button"><b>${esc(it.n)}</b><small>${it.d>0?'يطلع باليوم ~'+fmt(Math.round(it.d*10)/10)+' '+esc(it.u):'ما انصرف هالأسبوع'}</small></button>
        <div class="stk-q"><b>${fmt(Math.max(0,it.l))}</b><span>${esc(it.u)}</span>${it.l<0?`<small class="neg">الحساب ناقص ${fmt(-it.l)}</small>`:it.sub?`<small>${esc(it.sub())}</small>`:''}</div>
        <div class="stk-lv"><i style="width:${Math.round(lv*100)}%"></i></div>
        <div class="stk-d">${it.days!==null&&it.l>0?'يكفي '+(it.days<1?'أقل من يوم':(Math.round(it.days*10)/10)+' يوم'):''}</div>
        <span class="stk-st">${ST[it.st][0]}</span>
        <div class="stk-val">${it.val?fmt(Math.round(it.val))+' د.ع':''}</div>
        <div class="stk-a"><button class="ib" data-jard="${esc(it.k)}" type="button" aria-label="جرد ${esc(it.n)}">جرد</button><button class="ib" data-waste="${esc(it.k)}" type="button" aria-label="تلف ${esc(it.n)}">تلف</button></div>
      </div>` }).join('')+`</div></section>`).join('')||'<p class="note">كل شي متوفر 👌</p>'}
    ${stkLogHtml()}
    <p class="note" style="margin-top:8px">${lastJ?'آخر جرد: '+esc(lastJ.n)+' '+new Date(lastJ.ts).toLocaleDateString('ar-IQ-u-nu-latn',{weekday:'short',day:'numeric',month:'numeric'}):''}${lastJ?' · ':''}"يكفي" محسوب على معدل صرف آخر ٧ أيام من الطلبات.</p>`;
  v.querySelectorAll('[data-f]').forEach(b=>b.addEventListener('click',()=>{ stkFilter=b.dataset.f; stkRender() }));
  v.querySelectorAll('[data-jard]').forEach(b=>b.addEventListener('click',()=>stkAsk(b.dataset.jard,'jard')));
  v.querySelectorAll('[data-waste]').forEach(b=>b.addEventListener('click',()=>stkAsk(b.dataset.waste,'waste')));
  v.querySelectorAll('[data-card]').forEach(b=>b.addEventListener('click',()=>{ stkTab='qty'; stkRender(); const c=document.getElementById(b.dataset.card); if(c){ c.classList.remove('collapsed'); try{ c.scrollIntoView({behavior:'smooth',block:'start'}) }catch(_){} c.classList.add('stk-flash'); setTimeout(()=>c.classList.remove('stk-flash'),1600) } }));
}
/* تبويب الكميات: نخفي أرقام الأرباح (مكانها بالكلف) */
function stkTagRows(){ document.querySelectorAll('#page-store .card .trow').forEach(r=>{ const t=(r.firstElementChild||{}).textContent||''; if(/ربح|الكلفة الكلية|كلفة العلبة \(مع|إجمالي العلب|قيمة الشراء الكلية/.test(t)) r.classList.add('prof') }) }
setTimeout(()=>{ try{ stkTagRows() }catch(_){} },0);

const SAFI_VER='V126';
#page-store[data-tab="qty"] .trow.prof{display:none}
#stkView,.stk-tabs{max-width:1100px}
.kpi{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:12px}
.kpi>div{padding:14px 16px;border:1px solid var(--line2,#2a2c33);border-radius:14px;background:var(--paper,#111214);display:grid;gap:2px}
.kpi span{font-size:13px;color:#9296A0}
.kpi b{font-size:26px;line-height:1.2;font-variant-numeric:tabular-nums}
.kpi small{font-size:12px;color:#9296A0}
.kpi .bad b{color:#FF6B5E}.kpi .warn b{color:#F5A623}
.chips{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:14px}
.chips button{min-height:38px;padding:0 14px;border-radius:999px;border:1px solid var(--line2,#2a2c33);background:transparent;color:#C9CCD3;font:inherit;font-size:14px;cursor:pointer}
.chips button.on{background:#F5F5F2;color:#111;border-color:#F5F5F2}
.stk-t{border:1px solid var(--line2,#2a2c33);border-radius:14px;overflow:hidden;background:var(--paper,#111214)}
.stk-r{display:grid;grid-template-columns:minmax(150px,1.4fr) 120px minmax(80px,1fr) 110px 92px 110px auto;align-items:center;gap:12px;padding:10px 14px;border-top:1px solid var(--line2,#2a2c33)}
.stk-r:first-child{border-top:0}
.stk-n{background:none;border:0;color:inherit;font:inherit;text-align:right;cursor:pointer;padding:0;display:grid;gap:2px}
.stk-n b{font-size:15.5px;font-weight:600}.stk-n small{font-size:12px;color:#9296A0}
.stk-q{text-align:left}.stk-q b{font-size:21px;font-variant-numeric:tabular-nums}.stk-q span{font-size:12.5px;color:#9296A0;margin-inline-start:4px}
.stk-q small{display:block;font-size:11.5px;color:#9296A0}.stk-q small.neg{color:#F5A623}
.stk-lv{height:6px;border-radius:99px;background:#24262c;overflow:hidden}.stk-lv i{display:block;height:100%;border-radius:99px;background:#4ADE80}
.st-soon .stk-lv i{background:#F5A623}.st-low .stk-lv i,.st-out .stk-lv i{background:#FF6B5E}
.stk-d{font-size:13px;color:#C9CCD3}
.stk-st{justify-self:start;font-size:12.5px;font-weight:700;padding:4px 10px;border-radius:999px;background:rgba(74,222,128,.12);color:#4ADE80}
.st-soon .stk-st{background:rgba(245,166,35,.14);color:#F5A623}.st-low .stk-st,.st-out .stk-st{background:rgba(255,107,94,.14);color:#FF6B5E}
.st-out .stk-q b,.st-low .stk-q b{color:#FF6B5E}
.stk-val{font-size:13px;color:#9296A0;text-align:left;font-variant-numeric:tabular-nums}
.stk-a{display:flex;gap:6px}.ib{min-height:38px;padding:0 12px;border-radius:10px;border:1px solid var(--line2,#2a2c33);background:transparent;color:#C9CCD3;font:inherit;font-size:13.5px;cursor:pointer}
.ib:hover{border-color:#9296A0}
@media(max-width:900px){.kpi{grid-template-columns:repeat(2,1fr)}.stk-r{grid-template-columns:1fr auto auto;grid-template-areas:"n q a" "lv lv st" "d val val"}.stk-n{grid-area:n}.stk-q{grid-area:q}.stk-a{grid-area:a}.stk-lv{grid-area:lv}.stk-st{grid-area:st}.stk-d{grid-area:d}.stk-val{grid-area:val}}
